using Microsoft.EntityFrameworkCore;
namespace Society.Api;

public static partial class FinanceEndpoints {
 public static readonly string[] ReportNames=["Member Dues","Chapter Dues","Outstanding","Ageing","Collections","Invoices","Receipts","Reconciliation","Bank Cash Book","General Ledger","Trial Balance","Income Expenditure","Balance Sheet","Budget Actual","Event Finance","Donations","Inter Entity","Member Statement","Chapter Statement","Audit"];
 static void MapReports(RouteGroupBuilder t){
 t.MapGet("/conversions",async(Guid tenant,Guid entity,string target,DateOnly on,Guid? workspace,AppDb db,FinanceService service)=>{var e=await service.Require(tenant,entity,null);if(!FinanceService.Currencies.ContainsKey(target))throw new DomainException("Choose a supported reporting currency");var rate=e.Currency==target?1m:await db.Set<FinanceExchangeRate>().Where(r=>r.TenantId==tenant&&r.EntityId==entity&&r.FromCurrency==e.Currency&&r.ToCurrency==target&&r.Date==on).Select(r=>r.Rate).SingleOrDefaultAsync();if(rate<=0)throw new DomainException("Configure an explicit approved-source rate for the selected date");var invoices=service.Scoped<FinanceInvoice>(tenant,entity:entity,workspace:workspace).Where(i=>i.Status=="Issued"&&i.Kind=="Invoice");var balance=await invoices.SumAsync(i=>i.Total-i.Paid-i.Credited);return Results.Ok(new{entity=e.Name,sourceCurrency=e.Currency,reportingCurrency=target,rateDate=on,rate,sourceOutstanding=balance,convertedOutstanding=FinanceService.Round(balance*rate,target),basis="Operational translation of current receivables using the explicitly selected rate. No foreign-currency posting or statutory consolidation is implied."});});
 t.MapGet("/exchange-rates",async(Guid tenant,Guid entity,AppDb db,FinanceService service)=>{await service.Require(tenant,entity,null);return await db.Set<FinanceExchangeRate>().Where(r=>r.TenantId==tenant&&r.EntityId==entity).OrderByDescending(r=>r.Date).Take(100).Select(r=>new{r.Id,r.FromCurrency,r.ToCurrency,r.Rate,r.Date,r.Source}).ToListAsync();});

 t.MapGet("/dashboard",async(Guid tenant,Guid? entity,Guid? workspace,DateOnly? from,DateOnly? to,AppDb db,FinanceService s)=>{var start=from??new DateOnly(FinanceService.Today.Year,FinanceService.Today.Month,1);var end=to??FinanceService.Today;var invoices=s.Scoped<FinanceInvoice>(tenant,entity:entity,workspace:workspace).Where(i=>i.Kind=="Invoice"&&i.Status=="Issued");var payments=s.Scoped<FinancePayment>(tenant,entity:entity,workspace:workspace).Where(p=>p.Status=="Confirmed");var expenses=s.Scoped<FinanceExpense>(tenant,entity:entity,workspace:workspace);var assessments=s.Scoped<DuesAssessment>(tenant,entity:entity,workspace:workspace);var units=s.Scoped<FinancialUnit>(tenant,entity:entity,workspace:workspace).Select(u=>u.UnitId);var journals=s.Scoped<JournalEntry>(tenant,entity:entity,workspace:workspace).Where(j=>j.Posted&&j.Date>=start&&j.Date<=end);return Results.Ok(new{from=start,to=end,formula="Receivables = issued invoice totals - applied credits - invoice allocations. Cash collections = confirmed receipts, separate from accrual income. Amounts are grouped by currency, never implicitly consolidated.",currencies=await db.Set<FinancialEntity>().Where(e=>e.TenantId==tenant&&(entity==null||e.Id==entity)&&db.Set<FinancialUnit>().Any(u=>u.EntityId==e.Id&&u.UnitId!=null&&units.Contains(u.UnitId))).Select(e=>e.Currency).Distinct().Select(currency=>new{currency,assessed=invoices.Where(i=>i.Currency==currency).Sum(i=>i.Total),credits=invoices.Where(i=>i.Currency==currency).Sum(i=>i.Credited),allocated=invoices.Where(i=>i.Currency==currency).Sum(i=>i.Paid),outstanding=invoices.Where(i=>i.Currency==currency).Sum(i=>i.Total-i.Paid-i.Credited),overdue=invoices.Where(i=>i.Currency==currency).Where(i=>i.DueOn<FinanceService.Today).Sum(i=>i.Total-i.Paid-i.Credited),memberDues=invoices.Where(i=>i.Currency==currency).Where(i=>i.MembershipId!=null&&i.EventId==null).Sum(i=>i.Total),chapterDues=invoices.Where(i=>i.Currency==currency).Where(i=>i.BilledUnitId!=null).Sum(i=>i.Total),collections=payments.Where(p=>p.Currency==currency&&p.Date>=start&&p.Date<=end).Sum(p=>p.Amount-p.Refunded-p.ChargedBack),today=payments.Where(p=>p.Currency==currency&&p.Date==FinanceService.Today).Sum(p=>p.Amount-p.Refunded-p.ChargedBack),expenses=expenses.Where(e=>e.Currency==currency&&(e.Status=="Approved"||e.Status=="Paid")&&e.Date>=start&&e.Date<=end).Sum(e=>e.Amount)}).ToListAsync(),pendingPayments=await payments.CountAsync(p=>p.SettledOn==null),expenseApprovals=await expenses.CountAsync(e=>e.Status=="Pending Approval"),chapters=await db.Units.CountAsync(u=>u.TenantId==tenant&&units.Contains(u.Id)&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")),chaptersAssessed=await assessments.Where(x=>x.ChapterId!=null).Select(x=>x.ChapterId).Distinct().CountAsync(),overdueChapters=await invoices.Where(i=>i.BilledUnitId!=null&&i.DueOn<FinanceService.Today&&i.Total>i.Paid+i.Credited).Select(i=>i.BilledUnitId).Distinct().CountAsync(),trends=await payments.Where(p=>p.Date>=FinanceService.Today.AddMonths(-11)).GroupBy(p=>new{p.Currency,year=p.Date.Year,month=p.Date.Month}).Select(g=>new{g.Key.Currency,g.Key.year,g.Key.month,received=g.Sum(p=>p.Amount),refunded=g.Sum(p=>p.Refunded)}).OrderBy(x=>x.year).ThenBy(x=>x.month).ToListAsync(),budgets=await s.Scoped<FinanceBudget>(tenant,entity:entity,workspace:workspace).Where(b=>b.Status=="Approved").GroupBy(b=>b.Currency).Select(g=>new{currency=g.Key,approved=g.Sum(b=>b.Amount)}).ToListAsync(),recentPayments=await payments.OrderByDescending(p=>p.At).Take(6).Select(p=>new{p.Id,p.Payer,p.Reference,p.Amount,p.Currency,p.Date,p.Method}).ToListAsync()});});
 t.MapGet("/reports/catalog",async(Guid tenant,Access a)=>{await a.Member(tenant);return ReportNames;});
 t.MapGet("/reports",async(Guid tenant,string report,Guid? entity,Guid? workspace,Guid? member,Guid? chapter,Guid? eventId,DateOnly? from,DateOnly? to,int? page,AppDb db,Access a,FinanceService s)=>await Report(tenant,report,entity,workspace,member,chapter,eventId,from,to,page,db,a,s));
 t.MapGet("/statements/member/{id:guid}",async(Guid tenant,Guid id,Guid? entity,DateOnly? from,DateOnly? to,AppDb db,Access a,FinanceService s)=>{await a.Member(tenant);var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id)??throw new AccessDeniedException();var own=await MembershipExperience.Owned(db,a.UserId,true).AnyAsync(owned=>owned.Id==m.Id&&owned.TenantId==tenant);if(!own)await a.Require(tenant,"finance.read",m.ChapterId);return await Statement(tenant,entity,id,null,from,to,db,s,own);});
 t.MapGet("/statements/chapter/{id:guid}",async(Guid tenant,Guid id,Guid? entity,DateOnly? from,DateOnly? to,AppDb db,Access a,FinanceService s)=>{await a.Require(tenant,"finance.read",id);return await Statement(tenant,entity,null,id,from,to,db,s,false);});
 t.MapGet("/ledger",async(Guid tenant,Guid entity,Guid? workspace,Guid? account,DateOnly? from,DateOnly? to,Guid? beforeId,DateOnly? before,int? page,AppDb db,FinanceService s)=>{var journals=s.Scoped<JournalEntry>(tenant,entity:entity,workspace:workspace).Where(j=>j.Posted);if(from!=null)journals=journals.Where(j=>j.Date>=from);if(to!=null)journals=journals.Where(j=>j.Date<=to);var q=from l in db.Set<JournalLine>() join j in journals on l.JournalId equals j.Id join ac in db.Set<LedgerAccount>() on l.AccountId equals ac.Id where l.TenantId==tenant&&(account==null||l.AccountId==account) select new{l.Id,j.Number,j.Date,j.Currency,j.Purpose,j.SourceKind,j.SourceId,ac.Code,ac.Name,ac.Type,l.Debit,l.Credit,l.Memo,l.UnitId};if(before!=null)q=q.Where(l=>l.Date<before||l.Date==before&&l.Id.CompareTo(beforeId??Guid.Empty)<0);var rows=await q.OrderByDescending(l=>l.Date).ThenByDescending(l=>l.Id).Take(101).ToListAsync();return Results.Ok(new{items=rows.Take(100),hasMore=rows.Count>100,next=rows.Count>100?new{before=rows[99].Date,beforeId=rows[99].Id}:null});});
 }
 static async Task<object> Statement(Guid tenant,Guid? entity,Guid? member,Guid? chapter,DateOnly? from,DateOnly? to,AppDb db,FinanceService s,bool self){var start=from??new DateOnly(FinanceService.Today.Year,1,1);var end=to??FinanceService.Today;if(end<start||end.DayNumber-start.DayNumber>3660)throw new DomainException("Choose a statement range up to ten years");var journals=self?db.Set<JournalEntry>().AsNoTracking().Where(j=>j.TenantId==tenant&&j.Posted&&(entity==null||j.EntityId==entity)):s.Scoped<JournalEntry>(tenant,entity:entity).Where(j=>j.Posted);var lines=from l in db.Set<JournalLine>() join j in journals on l.JournalId equals j.Id join account in db.Set<LedgerAccount>() on l.AccountId equals account.Id where l.TenantId==tenant&&account.Code=="1100"&&(member==null||l.MembershipId==member)&&(chapter==null||l.CounterpartyUnitId==chapter) select new{l.Id,j.EntityId,j.Date,j.Number,j.Currency,j.Purpose,j.SourceKind,j.SourceId,l.Debit,l.Credit};var balances=await lines.Where(l=>l.Date<=end).GroupBy(l=>new{l.EntityId,l.Currency}).Select(g=>new{g.Key.EntityId,g.Key.Currency,opening=g.Where(l=>l.Date<start).Sum(l=>l.Debit-l.Credit),charges=g.Where(l=>l.Date>=start).Sum(l=>l.Debit),creditsAndAllocations=g.Where(l=>l.Date>=start).Sum(l=>l.Credit),closing=g.Sum(l=>l.Debit-l.Credit)}).ToListAsync();return new{from=start,to=end,member,chapter,balances,items=await lines.Where(l=>l.Date>=start&&l.Date<=end).OrderBy(l=>l.Date).ThenBy(l=>l.Id).Take(1000).ToListAsync(),truncated=await lines.CountAsync(l=>l.Date>=start&&l.Date<=end)>1000,formula="Opening + accounts-receivable debits - accounts-receivable credits = closing. Unapplied payments are liabilities, not reductions of invoice balances."};}
 static async Task<object> Report(Guid tenant,string report,Guid? entity,Guid? workspace,Guid? member,Guid? chapter,Guid? eventId,DateOnly? from,DateOnly? to,int? page,AppDb db,Access a,FinanceService s){await a.Member(tenant);if(!ReportNames.Contains(report))throw new DomainException("Choose a supported report");var start=from??new DateOnly(FinanceService.Today.Year,1,1);var end=to??FinanceService.Today;if(end<start||end.DayNumber-start.DayNumber>3660)throw new DomainException("Report range must be valid and up to ten years");var invoices=s.Scoped<FinanceInvoice>(tenant,entity:entity,workspace:workspace).Where(i=>i.Date>=start&&i.Date<=end);if(member!=null)invoices=invoices.Where(i=>i.MembershipId==member);if(chapter!=null)invoices=invoices.Where(i=>i.BilledUnitId==chapter);if(eventId!=null)invoices=invoices.Where(i=>i.EventId==eventId);var payments=s.Scoped<FinancePayment>(tenant,entity:entity,workspace:workspace).Where(p=>p.Date>=start&&p.Date<=end);var journals=s.Scoped<JournalEntry>(tenant,entity:entity,workspace:workspace).Where(j=>j.Posted&&j.Date<=end);var skip=Page(page)*100;
 if(report is "Member Dues" or "Chapter Dues" or "Outstanding" or "Invoices"){if(report=="Member Dues")invoices=invoices.Where(i=>i.MembershipId!=null&&i.EventId==null&&i.Kind=="Invoice");if(report=="Chapter Dues")invoices=invoices.Where(i=>i.BilledUnitId!=null&&i.Kind=="Invoice");if(report=="Outstanding")invoices=invoices.Where(i=>i.Status=="Issued"&&i.Kind=="Invoice"&&i.Total>i.Paid+i.Credited);return new{report,from=start,to=end,total=await invoices.CountAsync(),items=await s.Enrich(await invoices.OrderByDescending(i=>i.Date).ThenBy(i=>i.Id).Skip(skip).Take(100).ToListAsync())};}
 if(report=="Ageing"){var posted=s.Scoped<JournalEntry>(tenant,entity:entity,workspace:workspace).Where(j=>j.Posted&&j.Date<=end);var balances=from l in db.Set<JournalLine>() join j in posted on l.JournalId equals j.Id join account in db.Set<LedgerAccount>() on l.AccountId equals account.Id where account.Code=="1100"&&l.InvoiceId!=null group l by l.InvoiceId into g select new{invoiceId=g.Key,balance=g.Sum(l=>l.Debit-l.Credit)};var q=from i in s.Scoped<FinanceInvoice>(tenant,entity:entity,workspace:workspace) join b in balances on i.Id equals b.invoiceId where i.Status=="Issued"&&i.Kind=="Invoice"&&i.Date<=end&&b.balance>0 select new{i.EntityId,i.Currency,i.DueOn,b.balance};return new{report,asOf=end,items=await q.GroupBy(i=>new{i.EntityId,i.Currency}).Select(g=>new{g.Key.EntityId,g.Key.Currency,current=g.Where(i=>i.DueOn>=end).Sum(i=>i.balance),days1To30=g.Where(i=>i.DueOn<end&&i.DueOn>=end.AddDays(-30)).Sum(i=>i.balance),days31To60=g.Where(i=>i.DueOn<end.AddDays(-30)&&i.DueOn>=end.AddDays(-60)).Sum(i=>i.balance),days61To90=g.Where(i=>i.DueOn<end.AddDays(-60)&&i.DueOn>=end.AddDays(-90)).Sum(i=>i.balance),over90=g.Where(i=>i.DueOn<end.AddDays(-90)).Sum(i=>i.balance)}).ToListAsync(),basis="Historical as-of balances reconstructed from immutable invoice-linked accounts-receivable postings, including later credit and refund-allocation reversals only when posted by the cutoff."};}

 if(report is "Trial Balance" or "Income Expenditure" or "Balance Sheet" or "General Ledger" or "Bank Cash Book"){var q=from l in db.Set<JournalLine>() join j in journals on l.JournalId equals j.Id join ac in db.Set<LedgerAccount>() on l.AccountId equals ac.Id where l.TenantId==tenant select new{j.EntityId,j.UnitId,j.Date,j.Currency,j.Number,j.Purpose,j.SourceKind,j.SourceId,ac.Code,ac.Name,ac.Type,l.Id,l.Debit,l.Credit};if(report is "Income Expenditure")q=q.Where(l=>l.Date>=start&&(l.Type=="Income"||l.Type=="Expense"));if(report=="Bank Cash Book")q=q.Where(l=>l.Date>=start&&(l.Code=="1000"||l.Code=="1010"||l.Code=="1020"));if(report=="General Ledger")q=q.Where(l=>l.Date>=start);if(report is "Trial Balance" or "Income Expenditure" or "Balance Sheet"){var rows=await q.GroupBy(l=>new{l.EntityId,l.Currency,l.Code,l.Name,l.Type}).Select(g=>new{g.Key.EntityId,g.Key.Currency,g.Key.Code,g.Key.Name,g.Key.Type,debit=g.Sum(l=>l.Debit),credit=g.Sum(l=>l.Credit),balance=g.Sum(l=>l.Debit-l.Credit)}).OrderBy(l=>l.EntityId).ThenBy(l=>l.Code).ToListAsync();if(report=="Balance Sheet"){var summaries=rows.GroupBy(l=>new{l.EntityId,l.Currency}).Select(g=>new{g.Key.EntityId,g.Key.Currency,assets=g.Where(l=>l.Type=="Asset").Sum(l=>l.balance),liabilities=-g.Where(l=>l.Type=="Liability").Sum(l=>l.balance),funds=-g.Where(l=>l.Type=="Equity").Sum(l=>l.balance),currentSurplus=-g.Where(l=>l.Type=="Income"||l.Type=="Expense").Sum(l=>l.balance),difference=g.Sum(l=>l.balance)}).ToArray();var items=rows.Where(l=>l.Type is not("Income" or "Expense")).Concat(summaries.Select(g=>new{g.EntityId,g.Currency,Code="3999",Name="Current accumulated surplus / deficit",Type="Equity",debit=g.currentSurplus<0?-g.currentSurplus:0,credit=g.currentSurplus>0?g.currentSurplus:0,balance=-g.currentSurplus}));return new{report,asOf=end,items,summaries,basis="Assets = liabilities + funds + accumulated current surplus. Legal entities and currencies remain separate; unit-filtered views are operational segments."};}return new{report,from=start,to=end,items=rows,totalDebits=rows.GroupBy(l=>l.Currency).Select(g=>new{currency=g.Key,debit=g.Sum(l=>l.debit),credit=g.Sum(l=>l.credit),difference=g.Sum(l=>l.debit-l.credit)}),basis="Posted entity ledgers, split by entity/currency. Unit filters are operational segment views, not statutory legal-entity consolidation. Income/expense balances represent current surplus in the balance-sheet equation."};}return new{report,total=await q.CountAsync(),items=await q.OrderByDescending(l=>l.Date).ThenBy(l=>l.Id).Skip(skip).Take(100).ToListAsync()};}
 if(report=="Collections")return new{report,total=await payments.CountAsync(),items=await payments.OrderByDescending(p=>p.Date).Skip(skip).Take(100).Select(p=>new{p.Id,p.EntityId,p.UnitId,p.Payer,p.Reference,p.Date,p.Amount,p.Currency,p.Method,p.Status,p.SettledOn,p.Refunded,p.ChargedBack}).ToListAsync()};
 if(report=="Receipts"){var q=s.Scoped<FinanceReceipt>(tenant,entity:entity,workspace:workspace).Where(r=>r.At>=DateTime.SpecifyKind(start.ToDateTime(TimeOnly.MinValue),DateTimeKind.Utc)&&r.At<DateTime.SpecifyKind(end.AddDays(1).ToDateTime(TimeOnly.MinValue),DateTimeKind.Utc));return new{report,total=await q.CountAsync(),items=await q.OrderByDescending(r=>r.At).Skip(skip).Take(100).ToListAsync()};}
 if(report=="Reconciliation"){var q=s.Scoped<BankTransaction>(tenant,"finance.reconcile",entity,workspace).Where(b=>b.Date>=start&&b.Date<=end);return new{report,total=await q.CountAsync(),items=await q.OrderByDescending(b=>b.Date).Skip(skip).Take(100).ToListAsync()};}
 if(report=="Budget Actual"){var budgets=s.Scoped<FinanceBudget>(tenant,entity:entity,workspace:workspace);return new{report,items=await budgets.Take(100).Select(b=>new{b.Id,b.Name,b.EntityId,b.Currency,b.Amount,b.Status,committed=db.Set<FinanceExpense>().Where(x=>x.BudgetId==b.Id&&x.Status=="Pending Approval").Sum(x=>x.Amount),actual=db.Set<FinanceExpense>().Where(x=>x.BudgetId==b.Id&&(x.Status=="Approved"||x.Status=="Paid")).Sum(x=>x.Amount)}).ToListAsync()};}
 if(report=="Donations"){var q=s.Scoped<FinanceContribution>(tenant,entity:entity,workspace:workspace);return new{report,items=await q.OrderByDescending(c=>c.Date).Skip(skip).Take(100).Select(c=>new{c.Id,c.Kind,c.Purpose,c.EntityId,c.Currency,c.Pledged,c.Restricted,c.Status,c.InvoiceId,allocated=c.InvoiceId==null?0:db.Set<FinanceInvoice>().Where(i=>i.Id==c.InvoiceId).Select(i=>i.Paid).FirstOrDefault()}).ToListAsync(),basis="Pledges are promises; collections/allocated amounts require confirmed payment. No tax-deductibility claim."};}
 if(report=="Inter Entity")return new{report,items=await s.Scoped<InterEntityObligation>(tenant,entity:entity,workspace:workspace).OrderByDescending(x=>x.Date).Skip(skip).Take(100).ToListAsync(),basis="Obligation and settlement are separate. Fund allocations are not new revenue or completed bank transfers."};
 if(report=="Event Finance"){var inc=invoices.Where(i=>i.EventId!=null&&i.Kind=="Invoice"&&i.Status=="Issued");var expenses=s.Scoped<FinanceExpense>(tenant,entity:entity,workspace:workspace).Where(x=>x.EventId!=null&&(x.Status=="Approved"||x.Status=="Paid")&&x.Date>=start&&x.Date<=end);if(eventId!=null)expenses=expenses.Where(x=>x.EventId==eventId);return new{report,items=await inc.GroupBy(i=>new{i.EventId,i.EntityId,i.Currency}).Select(g=>new{g.Key.EventId,g.Key.EntityId,g.Key.Currency,invoiced=g.Sum(i=>i.Total),allocated=g.Sum(i=>i.Paid),outstanding=g.Sum(i=>i.Total-i.Paid-i.Credited),expenses=expenses.Where(x=>x.EventId==g.Key.EventId&&x.EntityId==g.Key.EntityId).Sum(x=>x.Amount)}).ToListAsync()};}
 if(report=="Member Statement"){if(member==null)throw new DomainException("Select a member");var m=await db.Memberships.SingleOrDefaultAsync(m=>m.Id==member&&m.TenantId==tenant)??throw new AccessDeniedException();await a.Require(tenant,"finance.read",m.ChapterId);return await Statement(tenant,entity,member,null,start,end,db,s,false);}
 if(report=="Chapter Statement"){if(chapter==null)throw new DomainException("Select a chapter");await a.Require(tenant,"finance.read",chapter);return await Statement(tenant,entity,null,chapter,start,end,db,s,false);}
 var visible=a.InWorkspace(a.Visible(tenant,"finance.read"),tenant,workspace).Select(u=>u.Id);var invoiceIds=s.Scoped<FinanceInvoice>(tenant,entity:entity,workspace:workspace).Select(i=>i.Id);var paymentIds=s.Scoped<FinancePayment>(tenant,entity:entity,workspace:workspace).Select(i=>i.Id);var journalIds=s.Scoped<JournalEntry>(tenant,entity:entity,workspace:workspace).Select(i=>i.Id);var expenseIds=s.Scoped<FinanceExpense>(tenant,entity:entity,workspace:workspace).Select(i=>i.Id);var audits=db.Audits.Where(x=>x.TenantId==tenant&&x.Action.StartsWith("finance.")&&(invoiceIds.Contains(x.ResourceId)||paymentIds.Contains(x.ResourceId)||journalIds.Contains(x.ResourceId)||expenseIds.Contains(x.ResourceId)));return new{report,total=await audits.CountAsync(),items=await audits.OrderByDescending(x=>x.At).Skip(skip).Take(100).ToListAsync()};
 }
}
